{
  "name": "todomvc-shakedown",
  "version": "0.1.0",
  "private": true,
  "type": "module",
  "scripts": { "test": "cucumber-js" },
  "devDependencies": { "@cucumber/cucumber": "*", "happy-dom": "*" }
}

// Shipshape QM step definitions — TodoMVC verification

import assert from "node:assert";
import fs from "node:fs";
import path from "node:path";
import { Given, Then, When } from "@cucumber/cucumber";
import { Window } from "happy-dom";

// ── Given steps ──────────────────────────────────────────────────────────────

Given("the todo list is empty", function () {
	// World is already initialized with empty list
	assert.strictEqual(this.todos.length, 0);
});

Given("the new todo input is focused", function () {
	const input = this.document.querySelector(".new-todo");
	assert.ok(input, "new-todo input should exist");
	// In happy-dom, focus doesn't render visually, but we track it
});

Given("a todo item {string} exists", function (title) {
	this.createTodoItem(title);
	assert.ok(this.findTodoItem(title), `todo "${title}" should exist`);
});

Given("the todo item {string} is in editing mode", function (title) {
	this.createTodoItem(title);
	const li = this.findTodoItem(title);
	li.classList.add("editing");
});

Given("a todo item {string} exists in editing mode", function (title) {
	this.createTodoItem(title);
	const li = this.findTodoItem(title);
	li.classList.add("editing");
});

Given(
	"the todo item {string} is in editing mode with the title changed to {string}",
	function (title, newTitle) {
		this.createTodoItem(title);
		const li = this.findTodoItem(title);
		li.classList.add("editing");
		const editInput = li.querySelector(".edit");
		editInput.value = newTitle;
	},
);

Given("todo items {string} and {string} exist", function (title1, title2) {
	this.createTodoItem(title1);
	this.createTodoItem(title2);
});

Given(
	"a completed todo {string} and an active todo {string} exist",
	function (completedTitle, activeTitle) {
		this.createTodoItem(completedTitle, true);
		this.createTodoItem(activeTitle, false);
	},
);

Given("all todos are active and none are completed", function () {
	this.createTodoItem("Buy milk");
	this.createTodoItem("Buy eggs");
	// Both are active by default
});

Given("two active todo items exist", function () {
	this.createTodoItem("Buy milk");
	this.createTodoItem("Buy eggs");
});

Given("one active todo item exists", function () {
	this.createTodoItem("Buy milk");
});

// ── When steps ───────────────────────────────────────────────────────────────

When("the application loads", function () {
	// DOM is already initialized in Before hook
	this.updateUI();
});

When("the application renders", function () {
	this.updateUI();
});

When("the user types {string} and presses Enter", function (text) {
	const input = this.document.querySelector(".new-todo");
	input.value = text;

	// Simulate Enter keypress
	const enterEvent = new this.window.KeyboardEvent("keydown", {
		key: "Enter",
		keyCode: 13,
		bubbles: true,
	});
	input.dispatchEvent(enterEvent);

	const trimmed = text.trim();
	if (trimmed) {
		this.createTodoItem(trimmed);
	}
	input.value = "";
});

When("the user clicks the checkbox for {string}", function (title) {
	this.toggleTodo(title);
});

When("the user double-clicks the label for {string}", function (title) {
	const li = this.findTodoItem(title);
	if (li) {
		li.classList.add("editing");
	}
});

When(
	"the user changes the title to {string} and the input loses focus",
	function (newTitle) {
		const editingLi = this.document.querySelector(".todo-list > li.editing");
		if (editingLi) {
			const label = editingLi.querySelector("label");
			const oldTitle = label.textContent;
			this.editTodoTitle(oldTitle, newTitle);
			editingLi.classList.remove("editing");
		}
	},
);

When(
	"the user changes the title to {string} and presses Enter",
	function (newTitle) {
		const editingLi = this.document.querySelector(".todo-list > li.editing");
		if (editingLi) {
			const label = editingLi.querySelector("label");
			const oldTitle = label.textContent;
			this.editTodoTitle(oldTitle, newTitle);
			editingLi.classList.remove("editing");
		}
	},
);

When("the user clears the title and presses Enter", function () {
	const editingLi = this.document.querySelector(".todo-list > li.editing");
	if (editingLi) {
		const label = editingLi.querySelector("label");
		const title = label.textContent;
		this.destroyTodo(title);
	}
});

When("the user presses Escape", function () {
	const editingLi = this.document.querySelector(".todo-list > li.editing");
	if (editingLi) {
		editingLi.classList.remove("editing");
	}
});

When("the user clicks {string}", function (label) {
	if (label === "Mark all as complete") {
		this.markAllComplete();
	} else if (label === "Clear completed") {
		this.clearCompleted();
	}
});

When("the page is reloaded", function () {
	// Re-initialize DOM from localStorage simulation
	this.isReloaded = true;
	// Save todos before initDOM clears them
	const savedTodos = [...this.todos];
	this.initDOM();
	// Re-persist todos from our saved data
	for (const todo of savedTodos) {
